D = "subs(diff({f},x),x,{a})"
def sl(f, a, v): return ("subs(diff(%s,x),x,%s)" % (f, a), v, "slope")
def va(f, a, v): return ("subs(%s,x,%s)" % (f, a), v, "value")
def tg(f, a, T): return ("subs(%s,x,%s)+subs(diff(%s,x),x,%s)*(x-(%s))" % (f, a, f, a, a), T, "tangent")
def df(f, d): return ("diff(%s,x)" % f, d, "derivative")

