def hand_rows(make_row, check, gdiag, Fn, poly_fn, tok, rid, sp, x):
    out = []
    for sub, dif, p, s_, a, cks in H:
        out.append(make_row("tangent", sub, dif, p, s_, a, [check(*c) for c in cks], "tangent_hand", row_id=rid(p)))
    return out
